#!/usr/bin/env python3
"""Self-contained patcher for RustDesk Windows x64 Embedded WireGuard Mod.

Usage:
  1. Extract Go user-space WireGuard SOCKS5 proxy source:
       python3 apply_windows_wg_changes.py --extract-wg-socks <out_dir>
  2. Apply Flutter UI + startup + HiDPI resolution fix patches inside rustdesk 1.5.3 root:
       python3 apply_windows_wg_changes.py
"""

import argparse
import base64
import pathlib
import sys

WG_SOCKS_FILES = {
    "go.mod": 'bW9kdWxlIHdnLXNvY2tzCgpnbyAxLjIyCgpyZXF1aXJlIGdvbGFuZy56eDJjNC5jb20vd2lyZWd1YXJkIHYwLjAuMC0yMDI1MDUyMTIzNDUwMi1mMzMzNDAyYmQ5Y2IK',
    "main.go": '',
    "main_test.go": '',
}

WG_TUNNEL_DART_B64 = ''


def replace_once(content: str, old: str, new: str, label: str) -> str:
    if new in content:
        print(f"[skip] already patched: {label}")
        return content
    count = content.count(old)
    if count != 1:
        raise RuntimeError(f"Expected exactly 1 match for {label}, found {count}")
    print(f"[ok] patched: {label}")
    return content.replace(old, new, 1)


def extract_wg_socks(out_dir: pathlib.Path) -> None:
    out_dir.mkdir(parents=True, exist_ok=True)
    for name, payload in WG_SOCKS_FILES.items():
        target = out_dir / name
        target.write_bytes(base64.b64decode(payload))
        print(f"[ok] wrote {target} ({target.stat().st_size} bytes)")


def apply_flutter_patches(repo_root: pathlib.Path) -> None:
    # 1. Write flutter/lib/utils/wg_tunnel.dart
    wg_dart = repo_root / "flutter" / "lib" / "utils" / "wg_tunnel.dart"
    wg_dart.parent.mkdir(parents=True, exist_ok=True)
    wg_dart.write_bytes(base64.b64decode(WG_TUNNEL_DART_B64))
    print(f"[ok] wrote {wg_dart} ({wg_dart.stat().st_size} bytes)")

    # 2. Patch flutter/lib/main.dart (import + startup init before mainCheckConnectStatus)
    main_dart = repo_root / "flutter" / "lib" / "main.dart"
    text = main_dart.read_text(encoding="utf-8")
    text = replace_once(
        text,
        "import 'models/platform_model.dart';",
        "import 'models/platform_model.dart';\nimport 'utils/wg_tunnel.dart';",
        "main.dart import wg_tunnel.dart",
    )
    text = replace_once(
        text,
        """void runMainApp(bool startService) async {
  // register uni links
  await initEnv(kAppTypeMain);
  checkUpdate();
  // trigger connection status updater
  await bind.mainCheckConnectStatus();""",
        """void runMainApp(bool startService) async {
  // register uni links
  await initEnv(kAppTypeMain);
  await WgTunnelService.instance.initOnStartup();
  checkUpdate();
  // trigger connection status updater
  await bind.mainCheckConnectStatus();""",
        "main.dart WgTunnelService.instance.initOnStartup()",
    )
    main_dart.write_text(text, encoding="utf-8")

    # 3. Patch flutter/lib/desktop/pages/desktop_setting_page.dart (Built-in WireGuard tile in Network card)
    setting_dart = repo_root / "flutter" / "lib" / "desktop" / "pages" / "desktop_setting_page.dart"
    text = setting_dart.read_text(encoding="utf-8")
    text = replace_once(
        text,
        "import 'package:flutter_hbb/models/state_model.dart';",
        "import 'package:flutter_hbb/models/state_model.dart';\nimport 'package:flutter_hbb/utils/wg_tunnel.dart';",
        "desktop_setting_page.dart import wg_tunnel.dart",
    )
    text = replace_once(
        text,
        """              if (!hideProxy)
                listTile(
                  icon: Icons.network_ping_outlined,
                  title: 'Socks5/Http(s) Proxy',
                  onTap: changeSocks5Proxy,
                ),""",
        """              if (!hideProxy)
                listTile(
                  icon: Icons.network_ping_outlined,
                  title: 'Socks5/Http(s) Proxy',
                  onTap: changeSocks5Proxy,
                ),
              if (isWindows && !isWeb) divider,
              if (isWindows && !isWeb)
                listTile(
                  icon: Icons.vpn_key_outlined,
                  title: '内置 WireGuard 隧道',
                  onTap: showWgTunnelSettingsDialog,
                  trailing: Obx(() {
                    final svc = WgTunnelService.instance;
                    final label = svc.statusLabel();
                    final Color color;
                    if (svc.running.value) {
                      color = Colors.green;
                    } else if (svc.lastError.value.isNotEmpty) {
                      color = Colors.red;
                    } else if (svc.starting.value) {
                      color = Colors.orange;
                    } else {
                      color = Colors.grey;
                    }
                    return Container(
                      padding: const EdgeInsets.symmetric(
                          horizontal: 10, vertical: 4),
                      decoration: BoxDecoration(
                        color: color.withOpacity(0.14),
                        borderRadius: BorderRadius.circular(12),
                        border: Border.all(color: color.withOpacity(0.45)),
                      ),
                      child: Text(
                        label,
                        style: TextStyle(
                          fontSize: 12,
                          color: color,
                          fontWeight: FontWeight.w500,
                        ),
                      ),
                    );
                  }),
                ),""",
        "desktop_setting_page.dart Built-in WireGuard tile",
    )
    setting_dart.write_text(text, encoding="utf-8")

    # 4. Patch flutter/lib/desktop/widgets/remote_toolbar.dart (fix Windows HiDPI resolution deadlock)
    toolbar_dart = repo_root / "flutter" / "lib" / "desktop" / "widgets" / "remote_toolbar.dart"
    text = toolbar_dart.read_text(encoding="utf-8")
    text = replace_once(
        text,
        """    final showOriginalBtn =
        ffiModel.isOriginalResolutionSet && !ffiModel.isOriginalResolution;""",
        """    final showOriginalBtn =
        (ffiModel.isOriginalResolutionSet && !ffiModel.isOriginalResolution) ||
            (pi.scaleOfDisplay(pi.currentDisplay) - 1.0).abs() > 0.01;""",
        "remote_toolbar.dart showOriginalBtn on HiDPI",
    )
    text = replace_once(
        text,
        """    if (w != null && h != null) {
      if (w != rect?.width.toInt() || h != rect?.height.toInt()) {
        await _changeResolution(w, h);
      }
    }""",
        """    if (w != null && h != null) {
      // Always dispatch ChangeResolution so HiDPI logical/physical size equality
      // (e.g. 3840x2160 @ scale=2.0 -> scaledRect 1920x1080) never blocks switching.
      await _changeResolution(w, h);
    }""",
        "remote_toolbar.dart always dispatch _changeResolution",
    )
    toolbar_dart.write_text(text, encoding="utf-8")


def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument(
        "--extract-wg-socks",
        metavar="DIR",
        help="Extract embedded wg-socks Go sources to DIR and exit",
    )
    parser.add_argument(
        "--repo-root",
        default=".",
        help="Path to RustDesk repository root (default: current directory)",
    )
    args = parser.parse_args()

    if args.extract_wg_socks:
        extract_wg_socks(pathlib.Path(args.extract_wg_socks))
        return

    apply_flutter_patches(pathlib.Path(args.repo_root).resolve())
    print("[done] all Windows WireGuard & Resolution Fix patches applied successfully.")


if __name__ == "__main__":
    try:
        main()
    except Exception as exc:
        print(f"[ERROR] {exc}", file=sys.stderr)
        sys.exit(1)
